,p_plug_name=>'Top 5 Products'
,p_title=>'Top 5 Products'
,p_parent_plug_id=>wwv_flow_imp.id(95141601658084999641)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    L_RESULT CLOB := ''<h4>Top 5 Products:</h4>'';',
'BEGIN',
'    L_RESULT := L_RESULT || ''<ul>'';',
'FOR L_EMP IN (',
'    SELECT',
'        PO.PRODUCT_NAME,',
'        PO.ORDER_COUNT,',
'        P.UNIT_PRICE,',
'        P.PRODUCT_IMAGE',
'FROM',
'         PRODUCT_ORDERS PO',
'    JOIN PRODUCTS P ON PO.PRODUCT_NAME = P.PRODUCT_NAME',
'WHERE',
'        PO.ORDER_STATUS = ''COMPLETE''',
'    AND ROWNUM <= 5',
'ORDER BY',
'    PO.ORDER_COUNT DESC',
') LOOP',
'L_RESULT := L_RESULT',
'            || ''<li><strong>''',
'            || APEX_ESCAPE.HTML(L_EMP.PRODUCT_NAME)',
'            || ''</strong>''',
'            || '' - ''',
'            || APEX_ESCAPE.HTML(L_EMP.UNIT_PRICE)',
'            || ''</li>'';',
'    END LOOP;',
'    L_RESULT := L_RESULT || ''</ul>'';',
'    RETURN L_RESULT;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
